
<script setup lang="ts">
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import * as echarts from 'echarts'
import { DataLine, Money, Warning, Tickets, Van, Box } from '@element-plus/icons-vue'
import { dashboardApi, adminOrderApi } from '@/api'
import type { DashboardSummary, Order, TrendPoint, CategoryDistribution, HotMedicine } from '@/types'
import { dateTime, money, orderStatusType } from '@/utils'
const summary=ref<DashboardSummary>();const latest=ref<Order[]>([]);const orderTrend=ref<TrendPoint[]>([]);const salesTrend=ref<TrendPoint[]>([]);const distribution=ref<CategoryDistribution[]>([]);const hot=ref<HotMedicine[]>([]);const loading=ref(false);const trendEl=ref<HTMLElement>();const pieEl=ref<HTMLElement>();let trendChart:echarts.ECharts|undefined;let pieChart:echarts.ECharts|undefined
const cards=[{key:'todayOrderCount',title:'今日订单',icon:Tickets,color:'blue'},{key:'todaySalesAmount',title:'今日销售额',icon:Money,color:'orange',money:true},{key:'pendingOrderCount',title:'待处理订单',icon:DataLine,color:'purple'},{key:'lowStockCount',title:'库存预警',icon:Warning,color:'red'}]
const renderCharts=()=>{if(trendEl.value){trendChart?.dispose();trendChart=echarts.init(trendEl.value);trendChart.setOption({tooltip:{trigger:'axis'},grid:{left:36,right:20,top:32,bottom:28},xAxis:{type:'category',data:orderTrend.value.map(i=>i.date),axisLine:{lineStyle:{color:'#dce6f1'}},axisLabel:{color:'#8795a8'}},yAxis:[{type:'value',splitLine:{lineStyle:{color:'#eef3f8'}},axisLabel:{color:'#8795a8'}},{type:'value',splitLine:{show:false},axisLabel:{show:false}}],series:[{name:'订单数',type:'bar',data:orderTrend.value.map(i=>i.value),barMaxWidth:20,itemStyle:{color:'#6aaeff',borderRadius:[5,5,0,0]}},{name:'销售额',type:'line',yAxisIndex:1,data:salesTrend.value.map(i=>i.amount),smooth:true,symbolSize:7,itemStyle:{color:'#19b98a'},lineStyle:{width:3,color:'#19b98a'},areaStyle:{color:'rgba(25,185,138,.12)'}}]})}if(pieEl.value){pieChart?.dispose();pieChart=echarts.init(pieEl.value);pieChart.setOption({tooltip:{trigger:'item',formatter:'{b}<br/>¥{c} ({d}%)'},legend:{bottom:0,textStyle:{color:'#7c8b9f',fontSize:11}},series:[{type:'pie',radius:['50%','72%'],center:['50%','44%'],label:{show:false},data:distribution.value.map(i=>({name:i.categoryName,value:i.amount}))}]})}}
const load=async()=>{loading.value=true;try{[summary.value,orderTrend.value,salesTrend.value,distribution.value,hot.value,latest.value]=await Promise.all([dashboardApi.summary(),dashboardApi.orderTrend(),dashboardApi.salesTrend(),dashboardApi.category(),dashboardApi.hot(),adminOrderApi.page({page:1,size:5}).then(v=>v.records)]);await nextTick();renderCharts()}finally{loading.value=false}}
onMounted(()=>{load();window.addEventListener('resize',renderCharts)});onBeforeUnmount(()=>{window.removeEventListener('resize',renderCharts);trendChart?.dispose();pieChart?.dispose()})
</script>
<template><div class="dashboard" v-loading="loading"><div class="admin-page-head"><div><span class="eyebrow">OPERATIONS OVERVIEW</span><h1>运营控制中心</h1><p>订单、库存与经营数据的实时概览。</p></div><el-button type="primary" @click="load">刷新数据</el-button></div><section class="dashboard-banner"><div><span>单店即时配送系统</span><h2>让每一笔订单，都处在可掌控的节奏里。</h2><p>当前待处理 <b>{{summary?.pendingOrderCount||0}}</b> 单，库存预警 <b>{{summary?.lowStockCount||0}}</b> 项。</p></div><div class="banner-status"><span><i></i>系统运行正常</span><b>{{new Date().toLocaleDateString('zh-CN')}}</b></div></section><section class="stat-grid"><article v-for="card in cards" :key="card.key" class="stat-card"><div :class="['stat-icon',card.color]"><el-icon><component :is="card.icon"/></el-icon></div><div><span>{{card.title}}</span><b>{{card.money?money((summary as any)?.[card.key]):(summary as any)?.[card.key]??0}}</b><small v-if="card.key==='pendingOrderCount'">待接单 {{summary?.toAcceptCount||0}} · 待打包 {{summary?.toPackCount||0}}</small><small v-else-if="card.key==='lowStockCount'">请及时补充货品</small><small v-else>今日运营实时数据</small></div></article></section><section class="dashboard-grid"><article class="control-card chart-card"><div class="card-head"><div><h2>近 7 天经营趋势</h2><p>订单量与完成订单销售额</p></div><el-tag type="primary" effect="plain">近 7 日</el-tag></div><div ref="trendEl" class="chart"></div></article><article class="control-card chart-card"><div class="card-head"><div><h2>分类销售占比</h2><p>已完成订单商品金额</p></div></div><div ref="pieEl" class="chart"></div></article><article class="control-card order-board"><div class="card-head"><div><h2>最新订单</h2><p>优先处理待接单订单</p></div><el-button text type="primary" @click="$router.push('/admin/orders')">全部订单 →</el-button></div><div v-if="latest.length" class="mini-orders"><div v-for="o in latest" :key="o.id" class="mini-order"><span class="order-circle">药</span><div><b>{{o.orderNo}}</b><small>{{o.receiverName}} · {{dateTime(o.createTime)}}</small></div><el-tag :type="orderStatusType(o.orderStatus)" size="small">{{o.orderStatusName}}</el-tag><strong>{{money(o.orderAmount)}}</strong></div></div><div v-else class="small-empty">暂无订单</div></article><article class="control-card hot-board"><div class="card-head"><div><h2>热销药品榜</h2><p>按已完成订单数量排序</p></div><el-icon class="hot-icon"><DataLine/></el-icon></div><div v-if="hot.length" class="hot-list"><div v-for="(item,index) in hot" :key="item.medicineName" class="hot-row"><span :class="['rank',{'top':index<3}]">0{{index+1}}</span><img v-if="item.imageUrl" :src="item.imageUrl"/><span v-else class="hot-img">药</span><b>{{item.medicineName}}</b><small>{{item.salesQuantity}} 件</small></div></div><div v-else class="small-empty">暂无已完成订单数据</div></article></section></div></template>
