-template-columns:1.3fr .7fr;gap:18px}.chart-card{padding:20px}.card-head{display:flex;justify-content:space-between;align-items:flex-start}.card-head h2{font-size:15px;margin:0 0 5px}.card-head p{font-size:11px;color:#8b99ab;margin:0}.chart{height:265px}.order-board,.hot-board{padding:19px}.mini-orders{margin-top:13px}.mini-order{display:grid;grid-template-columns:32px 1fr auto auto;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid #f0f3f7}.mini-order:last-child{border:0}.order-circle{width:29px;height:29px;border-radius:10px;background:#eaf4ff;color:#1677ff;display:grid;place-items:center;font-size:13px}.mini-order b,.mini-order small{display:block}.mini-order b{font-size:12px;color:#405168}.mini-order small{font-size:10px;color:#94a1b2;margin-top:3px}.mini-order strong{font-size:12px;color:#ff6d2c}.hot-icon{color:#ff8a34;font-size:22px}.hot-list{margin-top:10px}.hot-row{display:grid;grid-template-columns:28px 30px 1fr auto;align-items:center;gap:9px;padding:10px 0;border-bottom:1px solid #f0f3f7}.hot-row:last-child{border:0}.rank{font-size:11px;color:#91a0b2}.rank.top{color:#ff7d2a;font-weight:700}.hot-row img,.hot-img{width:29px;height:29px;border-radius:9px;background:#edf6ff;object-fit:cover;display:grid;place-items:center;color:#1677ff;font-size:12px}.hot-row b{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.hot-row small{font-size:11px;color:#19b98a}.small-empty{text-align:center;color:#93a1b2;font-size:12px;padding:45px}@media(max-width:1100px){.stat-grid{grid-template-columns:repeat(2,1fr)}.dashboard-grid{grid-template-columns:1fr}}@media(max-width:650px){.dashboard-banner{padding:22px;align-items:flex-start}.dashboard-banner h2{font-size:20px}.banner-status{display:none}.stat-grid{grid-template-columns:1fr 1fr;gap:10px}.stat-card{padding:13px}.stat-card b{font-size:19px}.stat-icon{width:36px;height:36px}.chart{height:230px}.mini-order{grid-template-columns:30px 1fr auto}.mini-order strong{display:none}}</style>
